def bbox_artist(artist, renderer, props=None, fill=False):
    """Draw a debugging bounding-box around ``artist``. Used for
    layout diagnostics — mirrors :func:`matplotlib.patches.bbox_artist`.
    """
    try:
        from matplotlib.patches import bbox_artist as _impl
        return _impl(artist, renderer, props=props, fill=fill)
    except (ImportError, AttributeError):
        pass
    # Fallback: build a Rectangle covering the artist's window extent
    # and add it to the artist's axes.
    try:
        from matplotlib.patches import Rectangle
        bbox = artist.get_window_extent(renderer)
        if bbox is None: return None
        rect = Rectangle((bbox.x0, bbox.y0), bbox.width, bbox.height,
                          fill=fill, **(props or {}))
        ax = getattr(artist, 'axes', None)
        if ax is not None and hasattr(ax, 'add_patch'):
            ax.add_patch(rect)
        return rect
    except Exception:
        return None


def _get_packed_offsets(widths, total, sep, mode='fixed'):
    """Compute (offset, total_length) for packing ``widths`` into a row.

    - ``mode='fixed'`` uses the supplied ``sep`` between items.
    - ``mode='expand'`` distributes the remaining space evenly so the
      packed items exactly fill ``total``.
    - ``mode='equal'`` lays the items out at equal positions, ignoring
      the items' actual widths.

    Returns ``(offsets, total_length)`` matching upstream's signature.
    """
    n = len(widths)
    if n == 0:
        return [], total or 0
    if mode == 'expand' and total is not None:
        if n == 1:
            return [0.0], total
        sep = (total - sum(widths)) / (n - 1)
    elif mode == 'equal' and total is not None:
        step = total / n
        return [i * step for i in range(n)], total
    offsets = []
    pos = 0.0
    for w in widths:
        offsets.append(pos)
        pos += w + sep
    used = pos - (sep if n else 0)
    return offsets, total if total is not None else used


def _get_aligned_offsets(yheights, height, align='baseline'):
    """Compute vertical offsets to align children inside a row of
    ``height``. ``yheights`` are the heights of each child (or
    ``(descent, ascent)`` pairs for baseline alignment).

    Supported modes: ``'baseline'``, ``'top'``, ``'bottom'``, ``'center'``.
    """
    if not yheights:
        return [], height or 0
    if align == 'top':
        return [(height - h) for h in yheights], height
    if align == 'bottom':
        return [0.0 for _ in yheights], height
    if align == 'center':
        return [(height - h) / 2.0 for h in yheights], height
    # baseline: align using descent / ascent if pair-shaped, else center.
    out = []
    for h in yheights:
        if hasattr(h, '__len__') and len(h) == 2:
            descent, ascent = h
            out.append(descent)
        else:
            out.append((height - h) / 2.0)
    return out, height


class DraggableBase:
    """Mixin enabling click-and-drag for an artist. Real matplotlib
    wires this through the canvas event system; the shim just records
    callbacks so callers can rely on ``connect``/``disconnect``."""

    def __init__(self, ref_artist, use_blit=False):
        self.ref_artist = ref_artist
        self.use_blit = use_blit
        self._callbacks = []
        self.got_artist = False

    def connect(self):
        return self

    def disconnect(self):
        self._callbacks.clear()

    def on_motion(self, evt):  pass
    def on_pick(self, evt):    self.got_artist = True
    def on_release(self, evt): self.got_artist = False


class DraggableOffsetBox(DraggableBase):
    """Drag an :class:`OffsetBox` around its parent figure."""

    def __init__(self, ref_artist, offsetbox, use_blit=False):
        super().__init__(ref_artist, use_blit=use_blit)
        self.offsetbox = offsetbox

    def save_offset(self):
        # Capture the OffsetBox position at the start of a drag.
        self._start_offset = getattr(self.offsetbox, '_offset', (0, 0))

    def update_offset(self, dx, dy):
        x, y = self._start_offset
        if hasattr(self.offsetbox, 'set_offset'):
            self.offsetbox.set_offset((x + dx, y + dy))


class DraggableAnnotation(DraggableBase):
    """Drag an :class:`~matplotlib.text.Annotation` around its parent."""

    def save_offset(self):
        ann = self.ref_artist
        self._start_xy = getattr(ann, 'xy', (0, 0))

    def update_offset(self, dx, dy):
        ann = self.ref_artist
        x, y = self._start_xy
        if hasattr(ann, 'set_position'):
            ann.set_position((x + dx, y + dy))


# ─── Added: AuxTransformBox + DEBUG flag from upstream offsetbox.py ─


# Module-wide debug flag — upstream uses it to dump bbox info when set.
DEBUG = False


class AuxTransformBox(OffsetBox):
    """An :class:`OffsetBox` whose children are positioned by a user-
    supplied transform (e.g. data → display) rather than by the
    standard packer geometry. Useful for placing artists in a legend
    while preserving their data-coordinate geometry."""

    def __init__(self, aux_transform):
        super().__init__()
        self.aux_transform = aux_transform
        self._children = []

    def add_artist(self, a):
        self._children.append(a)

    def get_transform(self):
        return self.aux_transform

    def get_children(self):
        return list(self._children)

    def get_extent(self, renderer):
        # Without a real renderer, fall back to a 1x1 placeholder.
        return (0, 0, 1, 1)


# ─── Added: AnchoredOffsetbox methods ──────────────────────────────


# Loc-name → integer code mapping (matches Legend.codes).
AnchoredOffsetbox.codes = {
    'best': 0, 'upper right': 1, 'upper left': 2, 'lower left': 3,
    'lower right': 4, 'right': 5, 'center left': 6, 'center right': 7,
    'lower center': 8, 'upper center': 9, 'center': 10,
}


def _ao_get_bbox(self):           return getattr(self, '_bbox', None)
def _ao_get_bbox_to_anchor(self): return getattr(self, '_bbox_anchor', None)
def _ao_set_bbox_to_anchor(self, bbox, transform=None):
    self._bbox_anchor = bbox
def _ao_get_child(self):          return getattr(self, '_child', None)
def _ao_set_child(self, child):   self._child = child
def _ao_get_children(self):
    c = self.get_child()
    return [c] if c is not None else []
def _ao_get_window_extent(self, renderer=None): return None
def _ao_update_frame(self, bbox, fontsize=None): pass

AnchoredOffsetbox.get_bbox             = _ao_get_bbox
AnchoredOffsetbox.get_bbox_to_anchor   = _ao_get_bbox_to_anchor
AnchoredOffsetbox.set_bbox_to_anchor   = _ao_set_bbox_to_anchor
AnchoredOffsetbox.get_child            = _ao_get_child
AnchoredOffsetbox.set_child            = _ao_set_child
AnchoredOffsetbox.get_children         = _ao_get_children
AnchoredOffsetbox.get_window_extent    = _ao_get_window_extent
AnchoredOffsetbox.update_frame         = _ao_update_frame


