@property
def _ab_anncoords(self):
    return getattr(self, 'xycoords', 'data')
@_ab_anncoords.setter
def _ab_anncoords(self, v):
    self.xycoords = v
AnnotationBbox.anncoords = _ab_anncoords

@property
def _ab_xyann(self):
    return getattr(self, 'xybox', None) or self.xy
@_ab_xyann.setter
def _ab_xyann(self, v):
    self.xybox = v
AnnotationBbox.xyann = _ab_xyann

def _ab_get_fontsize(self):      return getattr(self, '_fontsize', 12)
def _ab_set_fontsize(self, s):   self._fontsize = s
def _ab_get_window_extent(self, renderer=None): return None
def _ab_update_positions(self, renderer=None): pass
def _ab_get_children(self):
    return [self.offsetbox] if self.offsetbox else []

AnnotationBbox.get_fontsize       = _ab_get_fontsize
AnnotationBbox.set_fontsize       = _ab_set_fontsize
AnnotationBbox.get_window_extent  = _ab_get_window_extent
AnnotationBbox.update_positions   = _ab_update_positions
AnnotationBbox.get_children       = _ab_get_children


