@property
def _ob_axes(self):           return getattr(self, '_axes_ref', None)
@_ob_axes.setter
def _ob_axes(self, ax):       self._axes_ref = ax
OffsetBox.axes = _ob_axes


def _ob_get_bbox(self, renderer=None): return None
def _ob_get_visible_children(self): return [c for c in self.get_children() if getattr(c, '_visible', True)]
def _ob_set_height(self, h):  self._height = h
def _ob_set_width(self, w):   self._width = w

OffsetBox.get_bbox             = _ob_get_bbox
OffsetBox.get_visible_children = _ob_get_visible_children
OffsetBox.set_height           = _ob_set_height
OffsetBox.set_width            = _ob_set_width


def _oi_get_bbox(self, renderer=None): return None
def _oi_get_data(self):  return self.image
def _oi_set_data(self, A): self.image = A
def _oi_get_zoom(self):    return self.zoom
def _oi_set_zoom(self, z): self.zoom = float(z)

OffsetImage.get_bbox = _oi_get_bbox
OffsetImage.get_data = _oi_get_data
OffsetImage.set_data = _oi_set_data
OffsetImage.get_zoom = _oi_get_zoom
OffsetImage.set_zoom = _oi_set_zoom


